<?php
require_once __DIR__.'/royal_media_core.php';
$id=(int)($_GET['id']??0);$p=rm_paca($conn,$rm_empresa,$id);if(!$p){http_response_code(404);exit('Paca no encontrada');}
// Payload sin datos personales ni URL pública: requiere acceso autorizado para verificar.
$scheme=(!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS']!=='off')?'https':'http';
$host=(string)($_SERVER['SERVER_NAME']??'');
if(!preg_match('/^[a-zA-Z0-9.-]+$/D',$host)){http_response_code(500);exit('Dominio no válido para el QR');}
$base=rtrim(str_replace('\\','/',dirname((string)($_SERVER['SCRIPT_NAME']??'/'))),'/');
$payload=$scheme.'://'.$host.$base.'/royal_media_verificar.php?token='.$p['qr_token'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR <?=rm_h($p['codigo_paca'])?></title><script src="royal_media_qrcode.js"></script><style>@page{size:letter;margin:12mm}body{font-family:Arial,sans-serif;margin:0;color:#111}.sheet{width:100%;text-align:center}.brand{font-size:27px;font-weight:900;margin:15px 0}.label{font-size:21px;font-weight:700}.code{font-size:32px;font-weight:900;letter-spacing:1px;margin:12px}.details{font-size:18px;line-height:1.6}.qr{display:flex;justify-content:center;margin:18px auto}.qr svg{width:155mm;max-width:95%;height:auto}.controls{padding:10px;text-align:center;background:#eee}@media print{.controls{display:none}}@media screen{.sheet{max-width:750px;margin:20px auto;padding:10px;border:1px solid #ddd}}</style></head><body><div class="controls"><button onclick="window.print()">Imprimir hoja carta</button> <a href="royal_media_paca.php?id=<?=$id?>">Volver</a></div><div class="sheet"><div class="brand"><?=rm_h(empresa_nombre_actual() ?: 'ROYAL PRESTIGE')?></div><div class="label">IDENTIFICACIÓN INDIVIDUAL DE PACA</div><div id="qr" class="qr"></div><div class="code"><?=rm_h($p['codigo_paca'])?></div><div class="details"><strong>Producto:</strong> <?=rm_h($p['producto_nombre'])?><br><strong>Lote:</strong> <?=rm_h($p['codigo_lote'] ?: 'Origen no identificado')?><br><strong>Ubicación:</strong> <?=rm_h($p['ubicacion_bodega']?:'Sin asignar')?></div><p>Escanear en bodega para verificar antes de despachar</p></div><script>try { RoyalMediaQR.render(document.getElementById('qr'),<?=json_encode($payload,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>); } catch(e){document.getElementById('qr').textContent='Error generando QR: '+e.message;}</script></body></html>
